  if (lang && lang !== 'text') pre.prepend(h('span', { class: 'lang' }, lang));
  const cp = h('button', { class: 'copy', onclick: e => { e.stopPropagation(); navigator.clipboard?.writeText(code); toast('Copied 📋'); } }, 'copy');
