  if (ex.pairs) t += 'Pairs: ' + ex.pairs.map(p => p[0] + ' = ' + p[1]).join('; ') + '\n';
  if (ex.buckets) t += 'Buckets: ' + ex.items.map(i => i.text + ' → ' + ex.buckets[i.bucket]).join('; ') + '\n';
  if (ex.text) t += 'Text: ' + ex.text + '\n';
